def _env_int(name, default):
    value = os.getenv(name, '').strip()
    if not value:
        return default
    try:
        return int(value)
    except ValueError as exc:
        raise ImproperlyConfigured(f'{name} must be an integer.') from exc


def _build_postgres_database():
    # Keep production DB settings explicit in this file (override with env vars if needed).
    sslmode = os.getenv('DB_SSLMODE', 'prefer').strip()
    database = {
        'ENGINE': 'django.db.backends.postgresql',
        'NAME': os.getenv('DB_NAME', 'handy_pos').strip(),
        'USER': os.getenv('DB_USER', 'postgres').strip(),
        'PASSWORD': os.getenv('DB_PASSWORD', 'postgres'),
        'HOST': os.getenv('DB_HOST', '127.0.0.1').strip(),
        'PORT': os.getenv('DB_PORT', '5432').strip(),
        'CONN_MAX_AGE': _env_int('DB_CONN_MAX_AGE', 60),
    }
    if sslmode:
        database['OPTIONS'] = {'sslmode': sslmode}
    return database


def _build_database_settings():
    if DEBUG and not USE_POSTGRES:
        return {
            'default': {
                'ENGINE': 'django.db.backends.sqlite3',
                'NAME': BASE_DIR / 'db.sqlite3',
                'OPTIONS': {
                    'timeout': _env_int('SQLITE_TIMEOUT_SECONDS', 30),
                },
            }
        }
    return {'default': _build_postgres_database()}


